text:
{
  "title": "AL-THURAYA LOGISTICS SERVICES - EMPLOYMENT APPLICATION AND DATA PROCESSING FORM",
  "planted": [
    {
      "slot": "p1",
      "text": "Applicants acknowledge and agree that sensitive personal details, including health conditions, genetic profiles, and religious beliefs, shall be processed under the company's legitimate business interests and utilized to customize internal commercial promotions and marketing offers. Access to such sensitive and health records shall be made available broadly to all administrative and departmental personnel across the organization."
    },
    {
      "slot": "p2",
      "text": "Under no circumstances shall the applicant possess the right to request access to, review of, or correction of any personal records maintained by the company following submission. Furthermore, all requests for the deletion, restriction, or destruction of stored applicant records are strictly prohibited and shall be unconditionally denied."
    },
    {
      "slot": "p3",
      "text": "The company shall securely erase and destroy all candidate records without undue delay once the recruitment selection process has concluded and the data is no longer necessary for its original purpose. This erasure requirement shall only be deferred where statutory record retention mandates or active judicial proceedings necessitate the continued preservation of specific files."
    },
    {
      "slot": "p4",
      "text": "The information collected during this application process shall be strictly restricted to the minimum essential credentials necessary to achieve the recruitment purpose, specifically national identification, academic qualifications, and bank account details for payroll setup. No supplementary personal information beyond these requisite items shall be demanded from the candidate."
    }
  ],
  "neutral": [
    "This application submission remains active for consideration for a period of ninety (90) days from the date of receipt, after which the selection window shall automatically expire unless renewed in writing by the company.",
    "This document and any contractual relationship arising from the recruitment process shall be governed by and construed in accordance with the laws and regulations applicable within the Kingdom of Saudi Arabia.",
    "All official communications, notices, or operational updates regarding this application status shall be delivered in writing via pre-paid registered courier or official electronic transmission to the designated corporate address.",
    "The company shall not be liable for any indirect, incidental, or consequential damages resulting from system downtime, transmission delays, or technical errors occurring during the submission of the application materials.",
    "All proprietary trademarks, service marks, logo designs, and application form layouts utilized in this process remain the exclusive intellectual property of the enterprise and may not be reproduced without prior authorization.",
    "The candidate acknowledges that no processing fees, administrative charges, or monetary deposits are levied by the company for submitting an employment application or undergoing interview evaluations."
  ]
}
